"""
NWBFile.notes: behaviors, session custom fields, repository links, ex vivo specimens (slices),
and the metadata-only banner. The provenance block is appended by the writer.
"""

from __future__ import annotations

from ..normalize.kv import key_values, repository_links
from ..normalize.text import humanize_code
from ..normalize.units import is_performed
from . import describe
from .context import MapContext
from .registry import MappingRule, rules

METADATA_ONLY_BANNER = (
    "METADATA-ONLY EXPORT: this file was generated by brainstem-nwb from BrainSTEM metadata. It contains no "
    "measured data (no acquisition, stimulus or processed data). The raw data is described in data_collection "
    "and in the conversion manifest."
)


@rules(
    MappingRule(
        id="notes.behaviors",
        destination="NWBFile.notes (section 'Behaviors')",
        sources=("modules.behavior.notes", "modules.behavior.behavioralassay", "modules.behavior.setup",
                 "personal_attributes.behavioralassay.name", "personal_attributes.behavioralassay.description",
                 "personal_attributes.setup.name", "personal_attributes.setup.description",
                 "personal_attributes.setup.location", "personal_attributes.behavioralassay.behavioral_paradigm",
                 "taxonomies.behavioralparadigm.name", "taxonomies.behavioralparadigm.rrid",
                 "taxonomies.behavioralcategory.name", "personal_attributes.setup.setup_type",
                 "taxonomies.setuptype.name"),
        transform="one line per behavior: assay name and description, behavioral paradigm and category, setup "
                  "name, location, setup type and description, notes, BrainSTEM id. Timing is in the epochs table "
                  "when the behavior is linked to an epoch",
        condition="the session has behaviors included for the subject",
        missing="BEHAVIOR_NO_TIMING (info) for behaviors not linked to any epoch",
    ),
    MappingRule(
        id="notes.session_fields",
        destination="NWBFile.notes (sections 'Session custom fields', 'Repository links')",
        sources=("stem.session.extra_content_json", "stem.session.repository_links_json"),
        transform="'key: value' lines; '<repository>: <url>' lines",
    ),
    MappingRule(
        id="notes.banner",
        destination="NWBFile.notes (first paragraph), NWBFile.keywords",
        sources=(),
        transform="METADATA-ONLY banner; keyword 'metadata-only'",
    ),
    MappingRule(
        id="specimens.slices",
        destination="NWBFile.slices",
        sources=("stem.specimenset.name", "stem.specimenset.description", "stem.specimenset.type",
                 "stem.specimenset.type_json", "stem.specimenset.preparation_conditions",
                 "stem.specimenset.preparation_datetime", "stem.specimenset.quality", "stem.specimenset.item_count",
                 "stem.specimen.local_identifier", "stem.specimen.type", "stem.specimen.laterality",
                 "stem.specimen.preparation_conditions", "stem.specimen.notes",
                 "modules.specimenprocedure.type", "modules.specimenprocedure.type_json",
                 "modules.specimenprocedure.date_time", "modules.specimenprocedure.notes"),
        transform="for each specimen set of the session: type, preparation time and conditions, quality, item "
                  "count, details; its specimens (identifier, type, laterality, conditions, notes); and its "
                  "performed specimen procedures (date, type, details, notes)",
        condition="the session has specimen sets (ex vivo sessions)",
        missing="state not_applicable for sessions without specimen sets",
    ),
)
def map_notes(ctx: MapContext) -> None:
    store = ctx.store
    session = ctx.unit.session
    epoch_behaviors = {str(e.get("behavior")) for e in ctx.unit.role("epoch") if e.get("behavior")}

    lines = []
    for behavior in sorted(ctx.unit.role("behavior"), key=lambda b: (b.get("order") or 0, b.pk)):
        parts = []
        assay_ref = store.fk(behavior, "behavioralassay")
        assay = assay_ref.record if assay_ref else None
        if assay is not None:
            details = [describe.notes_text(assay, "description")]
            paradigm = store.fk_record(assay, "behavioral_paradigm")
            if paradigm is not None:
                category = store.fk_record(paradigm, "category")
                details.append(f"paradigm {paradigm.get('name')}"
                               + (f", category {category.get('name')}" if category is not None else ""))
                if paradigm.get("rrid"):
                    details.append(str(paradigm.get("rrid")))
            detail = "; ".join(part for part in details if part)
            parts.append(f"assay {assay.get('name')}" + (f" ({detail})" if detail else ""))
        elif assay_ref is not None:
            parts.append(f"assay {assay_ref.name or assay_ref.pk} (not readable by the exporting user)")
        setup_ref = store.fk(behavior, "setup")
        setup = setup_ref.record if setup_ref else None
        if setup is not None:
            setup_type = store.fk_record(setup, "setup_type")
            details = [str(setup.get("location") or ""), str(setup_type.get("name")) if setup_type else "",
                       describe.notes_text(setup, "description")]
            detail = "; ".join(part for part in details if part)
            parts.append(f"setup {setup.get('name')}" + (f" ({detail})" if detail else ""))
        elif setup_ref is not None:
            parts.append(f"setup {setup_ref.name or setup_ref.pk} (not readable by the exporting user)")
        notes = describe.notes_text(behavior)
        if notes:
            parts.append(f"notes: {notes}")
        if behavior.pk not in epoch_behaviors:
            parts.append("no epoch (no timing recorded)")
            ctx.warn("BEHAVIOR_NO_TIMING", record=behavior, rule_id="notes.behaviors")
        lines.append(f"Behavior {describe.ref(behavior)}: " + "; ".join(parts))
    if lines:
        ctx.add_notes("Behaviors", lines)
        ctx.map("notes.behaviors", "NWBFile.notes#Behaviors", "present", "\n".join(lines), ctx.unit.role("behavior"))

    custom = [f"{key}: {value}" for key, value in key_values(session.get("extra_content_json"))]
    ctx.add_notes("Session custom fields", custom)
    links = [f"{repo}: {url}" for repo, url in repository_links(session.get("repository_links_json"))]
    ctx.add_notes("Repository links", links)
    if custom or links:
        ctx.map("notes.session_fields", "NWBFile.notes#Session", "present", "\n".join(custom + links), [session])

    map_slices(ctx)


def map_slices(ctx: MapContext) -> None:
    store = ctx.store
    if not ctx.unit.specimen_sets:
        ctx.map("specimens.slices", "NWBFile.slices", "not_applicable")
        return
    lines = []
    for specimen_set in ctx.unit.specimen_sets:
        parts = [humanize_code(str(specimen_set.get("type") or "specimen set"))]
        prepared = describe.when(specimen_set.get("preparation_datetime"))
        if prepared:
            parts.append(f"prepared {prepared}")
        conditions = specimen_set.get("preparation_conditions") or []
        if conditions:
            parts.append(f"conditions {describe.value_text(conditions)}")
        for key in ("quality", "item_count"):
            if specimen_set.get(key) not in (None, ""):
                parts.append(f"{key.replace('_', ' ')} {describe.value_text(specimen_set.get(key))}")
        details = describe.details_text(specimen_set.get("type_json"))
        if details:
            parts.append(details)
        description = describe.notes_text(specimen_set, "description")
        if description:
            parts.append(description)
        lines.append(f"Specimen set {specimen_set.get('name')} {describe.ref(specimen_set)}: " + "; ".join(parts))
        for specimen in sorted(store.referrers(specimen_set, "stem.specimen", "specimen_set"),
                               key=lambda s: (s.get("order") or 0, s.pk)):
            sparts = [humanize_code(str(specimen.get("type") or "specimen"))]
            if specimen.get("laterality") and specimen.get("laterality") != "not_applicable":
                sparts.append(f"laterality {humanize_code(str(specimen.get('laterality')))}")
            if specimen.get("preparation_conditions"):
                sparts.append(f"conditions {describe.value_text(specimen.get('preparation_conditions'))}")
            notes = describe.notes_text(specimen)
            if notes:
                sparts.append(f"notes: {notes}")
            ident = specimen.get("local_identifier") or specimen.pk
            lines.append(f"  - specimen {ident} {describe.ref(specimen)}: " + "; ".join(sparts))
        for procedure in sorted(store.referrers(specimen_set, "modules.specimenprocedure", "specimen_set"),
                                key=lambda p: (str(p.get("date_time") or ""), p.pk)):
            if not is_performed(procedure):
                continue
            pparts = []
            details = describe.details_text(procedure.get("type_json"))
            if details:
                pparts.append(details)
            notes = describe.notes_text(procedure)
            if notes:
                pparts.append(f"notes: {notes}")
            head = " — ".join(p for p in (describe.when(procedure.get("date_time")),
                                         humanize_code(str(procedure.get("type") or ""))) if p)
            body = f": {'; '.join(pparts)}" if pparts else ""
            lines.append(f"  - procedure {head} {describe.ref(procedure)}{body}")
    text = "\n".join(lines)
    ctx.nwbfile["slices"] = text
    ctx.map("specimens.slices", "NWBFile.slices", "present", text, ctx.unit.specimen_sets)
